components-block-pager--pager-default.js:
import { registerWebComponents } from '@domg-wc/common';
import { VlPagerComponent } from '@domg-wc/components/block';

registerWebComponents([VlPagerComponent]);

// change volgt wanneer de huidige pagina wijzigt; event.detail bevat currentPage, totalPage, itemsPerPage en
// totalItems. De pager toont zelf geen data: laad hier de rijen van de nieuwe pagina.
document.querySelector('vl-pager').addEventListener('change', (event) => {
    console.log(event.detail.currentPage);
});

